"use client";

import { useCallback, useMemo, useRef, type ReactNode } from "react";
import { useSearchParams } from "next/navigation";
import { FunnelX } from "lucide-react";
import { cn } from "@/lib/utils";
import { chavesNaUrl, limpezaDosFiltros, mostrarLimparFiltros } from "@/lib/helpers/filtros-ativos";
import { Tooltip } from "@/components/ui/tooltip";
import { useSetParams } from "@/lib/hooks/use-set-params";
import { useFiltrosPersistidos } from "@/lib/hooks/use-filtros-persistidos";
import { ViewsSalvasMenu } from "@/components/ui/views-salvas-menu";
import { useFiltrosPersistencia } from "@/components/ui/filtros-persistencia";
import type { FiltroConhecido } from "@/lib/helpers/views-salvas";
import type { FilterConfig, TabConfig } from "@/components/ui/filter-bar-config";
import { FilterControl } from "@/components/ui/filter-bar-controle";
import { ViewTabsPill } from "@/components/ui/filter-bar-abas";

export type {
  FilterConfig,
  FilterOption,
  FilterType,
  TabConfig,
} from "@/components/ui/filter-bar-config";
export { ViewTabsPill } from "@/components/ui/filter-bar-abas";

interface FilterBarProps {
  filters?: FilterConfig[];
  viewTabs?: TabConfig[];
  /** Nome do parâmetro de URL que guarda a visualização ativa. */
  viewParam?: string;
  /** Visualização usada quando a URL não traz `viewParam`. */
  defaultView?: string;
  /** Botões de contexto da tela (ex.: "Calendário editorial", "Gerar link"). Primeiro no cluster da direita. */
  contextActions?: ReactNode;
  /** Estrela de favorito — sempre por último à direita. */
  favorito?: ReactNode;
  /** @deprecated Use `contextActions`. Mantido como alias legado. */
  actions?: ReactNode;
  /**
   * Quando informado, ativa a persistência por usuário dos filtros desta tela
   * (capability persistencia-filtros-usuario): restaura o último filtro salvo na
   * abertura (se a URL não trouxer filtros) e salva alterações de forma
   * debounced. Sem `telaKey`, o comportamento permanece o atual. A leitura e a
   * gravação vêm do `FiltrosPersistenciaProvider`; sem ele, `telaKey` não grava
   * nada e o menu de views salvas não aparece.
   */
  telaKey?: string;
  /**
   * Opt-out da busca colapsável (padrão global = lupa que expande). Quando `true`, o
   * campo de busca fica sempre aberto (comportamento anterior).
   */
  buscaSempreAberta?: boolean;
  /**
   * Opt-out da linha única (padrão global = filtros e visões na mesma linha, com
   * rolagem horizontal dos filtros). Quando `true`, os filtros voltam a quebrar em
   * várias linhas (`flex-wrap`).
   */
  permitirQuebra?: boolean;
  /**
   * A tela recorta no navegador o que já carregou e o servidor não lê os filtros
   * (ex.: calendário do time). Com `true`, a barra escreve a URL pela History API
   * nativa (`history.replaceState`/`pushState`), que o Next sincroniza com
   * `useSearchParams` sem pedir a página de novo ao servidor. Vale para a
   * mudança de filtro, a restauração do filtro salvo e a aplicação de view.
   * Padrão: `router.replace`, como nas telas que filtram no servidor.
   */
  recorteLocal?: boolean;
  /**
   * Parâmetros que dizem onde a tela está, e não o recorte (ex.: `ano`, `mes` e
   * `dia` do calendário do time). Ficam fora das views salvas, não impedem a view
   * de aparecer como ativa e são mantidos ao aplicar uma view.
   */
  paramsDeNavegacao?: string[];
}

// Classes de chip, menu e item de seleção: fonte única em `pilula.tsx`
// (padrão "Pílula de ação e de seleção", premium-design v0.10.0).
// A escrita na URL (com o reset de página) é o `useSetParams` de
// `@/lib/hooks/use-set-params` (change catalogo-componentes-premium-design, D7).

export function FilterBar({
  filters = [],
  viewTabs = [],
  viewParam = "view",
  defaultView,
  contextActions,
  favorito,
  actions,
  telaKey,
  buscaSempreAberta = false,
  permitirQuebra = false,
  recorteLocal = false,
  paramsDeNavegacao,
}: FilterBarProps) {
  // `actions` é alias legado de `contextActions` (zona de botões de contexto).
  const contexto = contextActions ?? actions;
  const searchParams = useSearchParams();

  const activeView = searchParams.get(viewParam) ?? defaultView ?? viewTabs[0]?.value;

  // Chaves de URL que contam como filtro (daterange e faixa expandem em
  // De/Ate; a busca com `aoBuscar` fica de fora). Base tanto da restauração
  // quanto do salvamento persistido. Regra pura em `filtros-ativos.ts`.
  const filterKeys = useMemo(() => chavesNaUrl(filters), [filters]);

  // Limpadores das buscas fora da URL (`aoBuscar`), chamados pelo "Limpar
  // filtros" junto com a limpeza da URL (change
  // catalogo-filterbar-faixa-busca-correcoes, D2).
  const limpadoresLocais = useRef(new Map<string, () => void>());
  const registrarLimpador = useCallback((key: string, limpar: () => void) => {
    const mapa = limpadoresLocais.current;
    mapa.set(key, limpar);
    return () => {
      if (mapa.get(key) === limpar) mapa.delete(key);
    };
  }, []);

  const { limpar: limparPersistido } = useFiltrosPersistidos({
    telaKey,
    filterKeys,
    local: recorteLocal,
  });

  // Views salvas só com tela identificada E persistência declarada: sem o
  // `FiltrosPersistenciaProvider`, a barra filtra pela URL e não mostra o menu
  // (change catalogo-componentes-premium-design, D6).
  const persistencia = useFiltrosPersistencia();
  const mostrarViews = telaKey != null && persistencia !== null;

  // Opções que a tela oferece HOJE, no formato mínimo de que o menu de views
  // precisa para avisar "filtro indisponível" quando uma view guarda um projeto
  // que foi excluído (capability views-salvas). Só filtros com lista fechada
  // entram: busca, data e toggle não têm opção para desaparecer.
  const filtrosConhecidos = useMemo<FiltroConhecido[]>(
    () =>
      filters
        .filter((f) => (f.type === "select" || f.type === "multiselect") && f.options?.length)
        .map((f) => ({
          key: f.key,
          label: f.label,
          multiplo: f.type === "multiselect",
          valores: (f.options ?? []).map((o) => o.value),
        })),
    [filters],
  );

  const setParams = useSetParams({ local: recorteLocal });

  // "Limpar filtros" só quando limpa mais do que a busca, que já tem o próprio
  // `X` (change busca-um-x-por-campo, D3). Regra pura em `filtros-ativos.ts`.
  const mostrarLimpar = mostrarLimparFiltros(filters, (k) => searchParams.get(k));

  function clearAll() {
    setParams(limpezaDosFiltros(filters));
    for (const limpar of limpadoresLocais.current.values()) limpar();
    // Limpar filtros também apaga o estado persistido da tela, para que a
    // próxima abertura não restaure o filtro anterior.
    limparPersistido();
  }

  return (
    <div
      className={cn("mb-5 flex items-center justify-between gap-3", permitirQuebra && "flex-wrap")}
    >
      {/* Filtros — esquerda. Padrão: linha única com rolagem horizontal (os dropdowns
          são portados, então não são cortados). Opt-out `permitirQuebra` → flex-wrap. */}
      <div
        className={cn(
          "flex items-center gap-[10px]",
          permitirQuebra
            ? "flex-wrap"
            : "min-w-0 flex-1 [scrollbar-width:none] overflow-x-auto [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden",
        )}
      >
        {filters.map((filter) => (
          <FilterControl
            key={filter.key}
            filter={filter}
            searchParams={searchParams}
            setParams={setParams}
            buscaColapsavel={!buscaSempreAberta}
            registrarLimpador={registrarLimpador}
          />
        ))}
        {/* Ícone de funil com x, não `X`: o `X` fica reservado ao limpar de um
            campo, e o funil diz "filtros" (change busca-um-x-por-campo, D3). */}
        {mostrarLimpar && (
          <Tooltip label="Limpar filtros" side="bottom">
            <button
              onClick={clearAll}
              aria-label="Limpar filtros"
              className="flex h-9 w-9 shrink-0 cursor-pointer items-center justify-center rounded-full bg-[var(--yellow)] text-[var(--premium-black)] shadow-[var(--sh-gold)] transition-colors hover:bg-[var(--gold)] active:bg-[var(--amber)]"
            >
              <FunnelX size={16} strokeWidth={2.5} />
            </button>
          </Tooltip>
        )}
      </div>

      {/* Cluster da direita — ordem fixa: contexto → views → favorito. O menu de
          views salvas abre a zona de contexto (capability views-salvas): fica
          antes dos botões da tela, que continuam encostados nas abas. */}
      {(contexto != null || mostrarViews || viewTabs.length > 0 || favorito != null) && (
        <div className={cn("flex shrink-0 items-center gap-3", permitirQuebra && "flex-wrap")}>
          {mostrarViews && telaKey && (
            <ViewsSalvasMenu
              telaKey={telaKey}
              filtros={filtrosConhecidos}
              paramsDeNavegacao={paramsDeNavegacao}
              local={recorteLocal}
            />
          )}
          {contexto}
          {viewTabs.length > 0 && (
            <ViewTabsPill
              viewTabs={viewTabs}
              activeView={activeView}
              viewParam={viewParam}
              setParams={setParams}
            />
          )}
          {favorito}
        </div>
      )}
    </div>
  );
}

/**
 * Tipos e regras puras da `FilterBar`: a configuração de cada filtro e de cada
 * aba, e a busca e o limite das opções dos filtros de seleção.
 */
import type { useSearchParams } from "next/navigation";
import type { LucideIcon } from "lucide-react";

export type FilterType = "select" | "multiselect" | "daterange" | "toggle" | "search" | "faixa";

export interface FilterOption {
  value: string;
  label: string;
}

// Busca acento/caixa-insensível — mesmo padrão de multi-select.tsx / select.tsx.
const norm = (s: string) => s.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");

/** A partir deste tamanho a lista ganha campo de busca automaticamente. */
const BUSCA_A_PARTIR_DE = 8;

/**
 * Limite padrão de opções exibidas (sem termo) quando a busca está disponível e a
 * lista é longa — padrão global (capability filter-bar-busca-layout-global), no mesmo
 * espírito do filtro "Projeto" da Gestão de Demandas. `limiteVisivel` por filtro
 * sobrescreve; nunca corta quando não há busca (itens ficariam inacessíveis).
 */
const LIMITE_VISIVEL_PADRAO = 6;

export interface FilterConfig {
  /** Chave usada na URL (para `daterange` e `faixa` vira `<key>De` e `<key>Ate`). */
  key: string;
  label: string;
  type: FilterType;
  options?: FilterOption[];
  icon?: LucideIcon;
  /** Texto exibido quando nenhum valor está selecionado (tipos select). */
  placeholder?: string;
  /**
   * Força (ou oculta) o campo de busca nas opções (`select`/`multiselect`).
   * Default: automático — aparece quando há ao menos `BUSCA_A_PARTIR_DE` opções.
   */
  searchable?: boolean;
  /**
   * Limite de opções exibidas **enquanto não há termo de busca** (ex.: 5). Ao
   * digitar, a busca abrange a lista completa (não só as visíveis por padrão).
   */
  limiteVisivel?: number;
  /**
   * Chaves de URL que saem junto quando este filtro é limpo (`select` e
   * `multiselect`), na mesma escrita. Para filtros que só fazem sentido com
   * este preenchido (ex.: "Onde está" depende de "Responsável"), de modo que
   * não sobre parâmetro órfão na URL nem no filtro persistido.
   */
  limpaJunto?: string[];
  /**
   * Limites da `faixa` (filtro de faixa numérica, "de" e "até"). Obrigatórios
   * quando o tipo é `faixa`: o valor fora deles vai para o limite mais próximo.
   */
  min?: number;
  max?: number;
  /** Incremento dos campos da `faixa`. Padrão 1. */
  passo?: number;
  /**
   * Busca fora da URL (`search`): com a função, o termo fica só no estado do
   * componente e chega aqui com o mesmo atraso da busca pela URL, e `""` ao
   * limpar. Não vai para a URL, para os filtros persistidos nem para as views
   * salvas. Para buscas com dado pessoal (nome, e-mail). Pode mudar a cada
   * render: a barra a guarda em ref.
   */
  aoBuscar?: (termo: string) => void;
}

/** Atualizações de URL de um filtro, somando as chaves dependentes quando ele é limpo. */
export function comDependentes(
  filter: FilterConfig,
  valor: string | null,
): Record<string, string | null> {
  const updates: Record<string, string | null> = { [filter.key]: valor };
  if (valor === null) for (const k of filter.limpaJunto ?? []) updates[k] = null;
  return updates;
}

export function mostrarBuscaPara(filter: FilterConfig): boolean {
  return filter.searchable ?? (filter.options?.length ?? 0) >= BUSCA_A_PARTIR_DE;
}

/**
 * Limite efetivo de itens visíveis (sem termo). Usa `limiteVisivel` quando o filtro o
 * define; senão aplica `LIMITE_VISIVEL_PADRAO` **apenas quando a busca está
 * disponível** (do contrário os itens ocultos ficariam inacessíveis) e a lista é maior
 * que o limite. `null` = não cortar.
 */
function limiteEfetivo(filter: FilterConfig): number | null {
  if (filter.limiteVisivel != null) return filter.limiteVisivel;
  if (!mostrarBuscaPara(filter)) return null;
  const n = filter.options?.length ?? 0;
  return n > LIMITE_VISIVEL_PADRAO ? LIMITE_VISIVEL_PADRAO : null;
}

/**
 * Aplica busca/limite às opções de um filtro select/multiselect, preservando a
 * ordem fornecida pela tela (a FilterBar nunca reordena). Sem termo, corta no limite
 * efetivo; com termo, filtra a lista inteira.
 */
export function filtrarOpcoes(filter: FilterConfig, termo: string): FilterOption[] {
  const opcoes = filter.options ?? [];
  const t = norm(termo.trim());
  if (t) return opcoes.filter((o) => norm(o.label).includes(t));
  const lim = limiteEfetivo(filter);
  return lim != null ? opcoes.slice(0, lim) : opcoes;
}

export interface TabConfig {
  value: string;
  label: string;
  icon?: LucideIcon;
  /** Contagem exibida ao lado do rótulo (ex.: abas "Todas 128" da Tabela). */
  count?: number;
}

/** Leitura dos parâmetros da URL, como o `useSearchParams` devolve. */
export type ParamsDaUrl = ReturnType<typeof useSearchParams>;

/** Escrita na URL: `null` remove a chave. */
export type EscreverParams = (updates: Record<string, string | null>) => void;

"use client";

import { useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { navegarComTransicao } from "@/lib/view-transition";
import type { EscreverParams, TabConfig } from "@/components/ui/filter-bar-config";

/**
 * Grupo de tabs de visão com pílula deslizante (CSS, medida por ref — sem
 * `layoutId`/`domMax`) e troca de conteúdo via View Transitions quando disponível
 * (change animacoes-graficos-abas-transicoes).
 *
 * A `FilterBar` renderiza um grupo (o `viewParam` da tela) no cluster da direita.
 * Exportado para telas que precisam de um **segundo** grupo de abas em outro
 * lugar do layout e em outro param — caso das abas "Todas/Para hoje/Atrasadas"
 * (`?aba=`) da visão Tabela de demandas, que ficam acima da tabela. Reusar este
 * componente (com `useSetParams`) mantém uma só implementação de estado de aba em
 * searchParam, com o mesmo visual e o mesmo reset de página.
 */
export function ViewTabsPill({
  viewTabs,
  activeView,
  viewParam,
  setParams,
}: {
  viewTabs: TabConfig[];
  activeView: string | undefined;
  viewParam: string;
  setParams: EscreverParams;
}) {
  const listRef = useRef<HTMLDivElement>(null);
  const btnRefs = useRef<Record<string, HTMLButtonElement | null>>({});
  const [ind, setInd] = useState<{ left: number; width: number } | null>(null);

  useEffect(() => {
    const btn = activeView ? btnRefs.current[activeView] : null;
    const list = listRef.current;
    if (!btn || !list) return;
    const atualizar = () => setInd({ left: btn.offsetLeft, width: btn.offsetWidth });
    atualizar();
    const ro = new ResizeObserver(atualizar);
    ro.observe(list);
    return () => ro.disconnect();
  }, [activeView, viewTabs.length]);

  return (
    <div
      ref={listRef}
      className="relative flex gap-1 rounded-[var(--r-md)] bg-[var(--premium-bone)] p-1"
    >
      {ind && (
        <span
          aria-hidden
          className="absolute top-1 bottom-1 rounded-[var(--r-sm)] bg-[var(--premium-white)] shadow-[var(--sh-sm)] transition-[left,width] duration-200 ease-[var(--ease)] motion-reduce:transition-none"
          style={{ left: ind.left, width: ind.width }}
        />
      )}
      {viewTabs.map((tab) => {
        const active = tab.value === activeView;
        const Icon = tab.icon;
        return (
          <button
            key={tab.value}
            ref={(el) => {
              btnRefs.current[tab.value] = el;
            }}
            onClick={() => navegarComTransicao(() => setParams({ [viewParam]: tab.value }))}
            // Anuncia a opção ativa ao leitor de tela (change qg-cliente, spec
            // qg-cliente-lista): o destaque visual sozinho não basta.
            aria-pressed={active}
            className={cn(
              "relative z-[1] flex cursor-pointer items-center gap-[7px] rounded-[var(--r-sm)] px-4 py-2 text-[13px] font-medium transition-colors",
              active ? "font-bold text-[var(--premium-ink)]" : "text-[var(--premium-steel)]",
            )}
          >
            {Icon && <Icon size={15} />} {tab.label}
            {tab.count != null && (
              <span className="text-[11px] text-[var(--premium-gray)]">{tab.count}</span>
            )}
          </button>
        );
      })}
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { buscaLocal, chavesDaFaixa } from "@/lib/helpers/filtros-ativos";
import { DatePicker } from "@/components/ui/date-picker";
import { chipActive, chipBase, chipIdle, chipOn } from "@/components/ui/pilula";
import type { EscreverParams, FilterConfig, ParamsDaUrl } from "@/components/ui/filter-bar-config";
import { BuscaLocalControl, SearchFilterControl } from "@/components/ui/filter-bar-busca";
import { FaixaFilterControl } from "@/components/ui/filter-bar-faixa";
import { MultiSelectControl, SingleSelectControl } from "@/components/ui/filter-bar-selecao";

/** Um filtro da barra: escolhe o controle pelo tipo. */
export function FilterControl({
  filter,
  searchParams,
  setParams,
  buscaColapsavel,
  registrarLimpador,
}: {
  filter: FilterConfig;
  searchParams: ParamsDaUrl;
  setParams: EscreverParams;
  buscaColapsavel: boolean;
  registrarLimpador: (key: string, limpar: () => void) => () => void;
}) {
  const Icon = filter.icon;

  if (buscaLocal(filter) && filter.aoBuscar) {
    return (
      <BuscaLocalControl
        filter={filter}
        aoBuscar={filter.aoBuscar}
        colapsavel={buscaColapsavel}
        registrarLimpador={registrarLimpador}
      />
    );
  }

  if (filter.type === "search") {
    return (
      <SearchFilterControl
        filter={filter}
        searchParams={searchParams}
        setParams={setParams}
        colapsavel={buscaColapsavel}
      />
    );
  }

  if (filter.type === "toggle") {
    const active = searchParams.get(filter.key) === "1";
    return (
      <button
        onClick={() => setParams({ [filter.key]: active ? null : "1" })}
        aria-pressed={active}
        className={cn(chipBase, active ? chipOn : chipIdle)}
      >
        {Icon && (
          <Icon
            size={14}
            className={active ? "text-[var(--yellow)]" : "text-[var(--premium-gray)]"}
          />
        )}
        {filter.label}
      </button>
    );
  }

  if (filter.type === "daterange") {
    const [chaveDe, chaveAte] = chavesDaFaixa(filter);
    const de = searchParams.get(chaveDe) ?? "";
    const ate = searchParams.get(chaveAte) ?? "";
    const active = Boolean(de || ate);
    return (
      <div className={cn(chipBase, active ? chipActive : chipIdle, "cursor-default")}>
        {Icon && <Icon size={14} className="text-[var(--premium-gray)]" />}
        <span className="text-[var(--premium-gray)]">{filter.label}</span>
        <DatePicker
          variant="inline"
          value={de}
          max={ate || undefined}
          onChange={(e) => setParams({ [chaveDe]: e.target.value || null })}
          placeholder="Início"
          ariaLabel={`${filter.label}: data inicial`}
        />
        <span className="text-[var(--premium-gray)]">–</span>
        <DatePicker
          variant="inline"
          value={ate}
          min={de || undefined}
          onChange={(e) => setParams({ [chaveAte]: e.target.value || null })}
          placeholder="Fim"
          ariaLabel={`${filter.label}: data final`}
        />
      </div>
    );
  }

  if (filter.type === "faixa") {
    return <FaixaFilterControl filter={filter} searchParams={searchParams} setParams={setParams} />;
  }

  if (filter.type === "multiselect") {
    return <MultiSelectControl filter={filter} searchParams={searchParams} setParams={setParams} />;
  }

  // select (padrão) — pílula com dropdown custom (mesmo painel do multiselect).
  return <SingleSelectControl filter={filter} searchParams={searchParams} setParams={setParams} />;
}

"use client";

import { useEffect, useRef, useState, useTransition } from "react";
import { Search, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { campoAdotaUrl } from "@/lib/helpers/busca-filtro-url";
import { useBuscaLocal } from "@/lib/hooks/use-busca-local";
import { chipActive, chipBase, chipIdle } from "@/components/ui/pilula";
import type { EscreverParams, FilterConfig, ParamsDaUrl } from "@/components/ui/filter-bar-config";

// Filtro de busca por palavra-chave: input textual persistido na URL
// (`<key>`), com debounce para não thrashar o histórico enquanto digita. Tokens
// semânticos, foco visível e contraste AA em claro/escuro.
export function SearchFilterControl({
  filter,
  searchParams,
  setParams,
  colapsavel,
}: {
  filter: FilterConfig;
  searchParams: ParamsDaUrl;
  setParams: EscreverParams;
  colapsavel: boolean;
}) {
  const urlValue = searchParams.get(filter.key) ?? "";
  const [valor, setValor] = useState(urlValue);
  const [urlAnterior, setUrlAnterior] = useState(urlValue);
  // Escrita do campo a caminho da URL: o debounce correndo (`digitando`) ou a
  // navegação disparada por ele ainda sem confirmar (`navegando`). Estado, não
  // ref, porque é lido durante o render.
  const [digitando, setDigitando] = useState(false);
  const [navegando, startNavegacao] = useTransition();
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Reflete mudanças externas da URL (ex.: "Limpar filtros") no campo, sem
  // efeito: padrão "ajuste de estado durante o render" do React (rastreia o
  // último valor da URL via estado, não ref). Só quando não há escrita do campo
  // a caminho: a URL muda quando a resposta do servidor chega, e a resposta
  // atrasada de uma escrita anterior traz o termo antigo, que apagaria o que
  // acabou de ser digitado (change filter-bar-busca-digitacao-estavel).
  if (campoAdotaUrl({ urlValue, urlAnterior, escritaPendente: digitando || navegando })) {
    setUrlAnterior(urlValue);
    setValor(urlValue);
  }

  function onChange(v: string) {
    setValor(v);
    setDigitando(true);
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      setDigitando(false);
      // Na transição, `navegando` fica verdadeiro até a URL confirmar.
      startNavegacao(() => setParams({ [filter.key]: v.trim() || null }));
    }, 300);
  }

  function limpar() {
    setValor("");
    setDigitando(false);
    if (timer.current) clearTimeout(timer.current);
    startNavegacao(() => setParams({ [filter.key]: null }));
  }

  return (
    <ChipBusca
      filter={filter}
      valor={valor}
      onChange={onChange}
      onLimpar={limpar}
      colapsavel={colapsavel}
    />
  );
}

// Busca fora da URL (`aoBuscar`): o termo fica no estado do componente e chega
// à tela pela função, com o mesmo atraso (change
// catalogo-filterbar-faixa-busca-correcoes, D2). O limpador entra no registro
// da barra para o "Limpar filtros" esvaziar o campo e chamar `aoBuscar("")`.
export function BuscaLocalControl({
  filter,
  aoBuscar,
  colapsavel,
  registrarLimpador,
}: {
  filter: FilterConfig;
  aoBuscar: (termo: string) => void;
  colapsavel: boolean;
  registrarLimpador: (key: string, limpar: () => void) => () => void;
}) {
  const { valor, alterar, limpar } = useBuscaLocal({ aoBuscar });

  useEffect(() => registrarLimpador(filter.key, limpar), [registrarLimpador, filter.key, limpar]);

  return (
    <ChipBusca
      filter={filter}
      valor={valor}
      onChange={alterar}
      onLimpar={limpar}
      colapsavel={colapsavel}
    />
  );
}

// Chip da busca, o mesmo para a busca pela URL e para a busca fora dela: a
// lupa colapsável, o campo e o `X` de limpar.
function ChipBusca({
  filter,
  valor,
  onChange,
  onLimpar,
  colapsavel,
}: {
  filter: FilterConfig;
  valor: string;
  onChange: (v: string) => void;
  onLimpar: () => void;
  colapsavel: boolean;
}) {
  const Icon = filter.icon ?? Search;
  const [expandido, setExpandido] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const active = valor.trim().length > 0;
  // Aberto quando: não-colapsável (opt-out), expandido manualmente, ou há termo.
  const aberto = !colapsavel || expandido || active;

  // Foca o input ao expandir (capability filter-bar-busca-layout-global).
  useEffect(() => {
    if (aberto && expandido) inputRef.current?.focus();
  }, [aberto, expandido]);

  function limpar() {
    onLimpar();
    setExpandido(false);
  }

  // Um único elemento que cresce suavemente: a lupa fica sempre visível e o campo
  // anima a largura/opacidade de 0 → 200px ao abrir (capability
  // filter-bar-busca-layout-global). `overflow-hidden` esconde o campo recolhido.
  return (
    <div
      className={cn(
        chipBase,
        active ? chipActive : chipIdle,
        "shrink-0 overflow-hidden",
        aberto ? "cursor-text gap-2" : "cursor-pointer gap-0",
      )}
      onClick={() => {
        if (colapsavel && !aberto) setExpandido(true);
      }}
    >
      <button
        type="button"
        onClick={(e) => {
          if (colapsavel && !aberto) {
            e.stopPropagation();
            setExpandido(true);
          }
        }}
        aria-label={filter.label}
        aria-expanded={aberto}
        tabIndex={aberto ? -1 : 0}
        className="flex shrink-0 items-center justify-center focus-visible:rounded-full focus-visible:ring-2 focus-visible:ring-[var(--yellow-50)] focus-visible:outline-none"
      >
        <Icon size={18} className="text-[var(--premium-gray)]" />
      </button>
      <input
        ref={inputRef}
        type="search"
        value={valor}
        onChange={(e) => onChange(e.target.value)}
        onBlur={() => {
          if (!valor.trim()) setExpandido(false);
        }}
        onKeyDown={(e) => {
          if (e.key === "Escape" && !valor.trim()) setExpandido(false);
        }}
        placeholder={filter.placeholder ?? filter.label}
        aria-label={filter.label}
        aria-hidden={!aberto}
        tabIndex={aberto ? 0 : -1}
        style={{ width: aberto ? 200 : 0, opacity: aberto ? 1 : 0 }}
        className="bg-transparent text-[13px] text-[var(--premium-ink)] transition-[width,opacity] duration-200 ease-out placeholder:text-[var(--premium-gray)] focus:outline-none"
      />
      {/* O único controle de limpar do campo: o "x" nativo do type="search" é
          escondido pela regra base do globals.css (change busca-um-x-por-campo).
          Alvo de 24×24px (antes o ícone de 14px era o próprio alvo); o -mr
          devolve o respiro direito do chip. Limpar recolhe o chip, então o foco
          não volta ao campo, que some. */}
      {active && (
        <button
          type="button"
          onClick={limpar}
          aria-label="Limpar busca"
          className="-mr-[5px] flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-[var(--premium-gray)] hover:text-[var(--premium-ink)] focus-visible:ring-2 focus-visible:ring-[var(--yellow-50)] focus-visible:outline-none"
        >
          <X size={14} />
        </button>
      )}
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { m } from "motion/react";
import { ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  chavesDaFaixa,
  escritaDaFaixa,
  normalizarFaixa,
  rotuloFaixa,
  type LimitesFaixa,
} from "@/lib/helpers/filtros-ativos";
import { motionPreset } from "@/lib/motion";
import { popoverPos } from "@/lib/popover-pos";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  chipActive,
  chipBase,
  chipIdle,
  dropdownPanelClass,
  useDropdownPortal,
} from "@/components/ui/pilula";
import type { EscreverParams, FilterConfig, ParamsDaUrl } from "@/components/ui/filter-bar-config";

/** Limites da `faixa`, obrigatórios em tempo de execução (D1). */
function limitesDaFaixa(filter: FilterConfig): LimitesFaixa {
  const { min, max } = filter;
  if (
    typeof min !== "number" ||
    typeof max !== "number" ||
    !Number.isFinite(min) ||
    !Number.isFinite(max) ||
    min > max
  ) {
    throw new Error(
      `FilterBar: o filtro "${filter.key}" é do tipo "faixa" e precisa de min e max numéricos, com min <= max.`,
    );
  }
  return { min, max };
}

const textoDe = (n: number | null) => (n === null ? "" : String(n));

// Filtro de faixa numérica, "de" e "até" (change
// catalogo-filterbar-faixa-busca-correcoes, D1): pílula com o rótulo resumido
// e o painel em portal dos selects, com dois campos numéricos. Grava
// `<key>De`/`<key>Ate` ao confirmar (Enter ou Aplicar), ao sair dos campos ou
// ao fechar o painel pelo clique fora, nunca a cada tecla; `Esc` descarta.
export function FaixaFilterControl({
  filter,
  searchParams,
  setParams,
}: {
  filter: FilterConfig;
  searchParams: ParamsDaUrl;
  setParams: EscreverParams;
}) {
  const { open, setOpen, rect, triggerRef, panelRef, abrir } = useDropdownPortal();
  const id = useId();
  const Icon = filter.icon;
  const limites = limitesDaFaixa(filter);
  const passo = filter.passo ?? 1;
  const [chaveDe, chaveAte] = chavesDaFaixa(filter);
  const urlDe = searchParams.get(chaveDe);
  const urlAte = searchParams.get(chaveAte);
  const atual = normalizarFaixa(urlDe, urlAte, limites);
  const active = atual.de !== null || atual.ate !== null;
  const rotulo = rotuloFaixa(filter.label, atual);
  const [de, setDe] = useState("");
  const [ate, setAte] = useState("");
  // Edição ainda não gravada; `null` quando não há nada pendente.
  const pendente = useRef<{ de: string; ate: string } | null>(null);

  /** Grava na URL, só quando muda algo. */
  function escrever(novoDe: string, novoAte: string) {
    pendente.current = null;
    const escrita = escritaDaFaixa(filter, novoDe, novoAte, limites);
    if (escrita[chaveDe] !== (urlDe || null) || escrita[chaveAte] !== (urlAte || null))
      setParams(escrita);
  }

  /** Grava e mostra nos campos o valor normalizado (limitado e ordenado). */
  function aplicar(novoDe: string, novoAte: string) {
    const v = normalizarFaixa(novoDe, novoAte, limites);
    setDe(textoDe(v.de));
    setAte(textoDe(v.ate));
    escrever(novoDe, novoAte);
  }

  // Fechou pelo clique fora com edição pendente: grava, como ao sair do campo.
  const escreverRef = useRef(escrever);
  useEffect(() => {
    escreverRef.current = escrever;
  });
  useEffect(() => {
    if (!open && pendente.current) escreverRef.current(pendente.current.de, pendente.current.ate);
  }, [open]);

  function abrirPainel() {
    setDe(textoDe(atual.de));
    setAte(textoDe(atual.ate));
    pendente.current = null;
    abrir();
  }

  function fechar() {
    setOpen(false);
    triggerRef.current?.focus();
  }

  function onKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key === "Enter") {
      e.preventDefault();
      aplicar(de, ate);
      fechar();
    } else if (e.key === "Escape") {
      // O `useDropdownPortal` fecha o painel; a edição é descartada.
      pendente.current = null;
      triggerRef.current?.focus();
    }
  }

  function onBlur(e: React.FocusEvent<HTMLInputElement>) {
    // Ir de um campo ao outro, ou aos botões do painel, não grava.
    if (panelRef.current?.contains(e.relatedTarget as Node | null)) return;
    if (pendente.current) aplicar(de, ate);
  }

  function mudarDe(v: string) {
    setDe(v);
    pendente.current = { de: v, ate };
  }

  function mudarAte(v: string) {
    setAte(v);
    pendente.current = { de, ate: v };
  }

  // O que os dois campos têm em comum: número com os limites e o passo, e as
  // mesmas teclas e a mesma saída.
  const propsCampo = {
    type: "number",
    inputMode: Number.isInteger(passo) && Number.isInteger(limites.min) ? "numeric" : "decimal",
    min: limites.min,
    max: limites.max,
    step: passo,
    onKeyDown,
    onBlur,
    className: "min-h-10",
  } as const;

  return (
    <div className="relative shrink-0">
      <button
        ref={triggerRef}
        type="button"
        onClick={() => (open ? setOpen(false) : abrirPainel())}
        aria-haspopup="dialog"
        aria-expanded={open}
        className={cn(
          chipBase,
          active ? chipActive : chipIdle,
          "focus-visible:shadow-[0_0_0_2px_var(--yellow-50),0_0_0_3px_var(--premium-ink)] focus-visible:outline-none",
        )}
      >
        {Icon && <Icon size={14} className="text-[var(--premium-gray)]" />}
        <span>{rotulo}</span>
        <ChevronDown size={14} className="-mr-1 text-[var(--premium-gray)]" />
      </button>
      {open &&
        rect &&
        typeof document !== "undefined" &&
        createPortal(
          <m.div
            ref={panelRef}
            {...motionPreset("menu")}
            role="dialog"
            aria-label={filter.label}
            style={popoverPos(rect, Math.max(rect.width, 260), 200)}
            className={cn(dropdownPanelClass, "p-3")}
          >
            <div className="grid grid-cols-2 gap-3">
              <Input
                {...propsCampo}
                id={`${id}-de`}
                label="De"
                aria-label={`${filter.label}: de`}
                value={de}
                onChange={(e) => mudarDe(e.target.value)}
                placeholder={String(limites.min)}
                autoFocus
              />
              <Input
                {...propsCampo}
                id={`${id}-ate`}
                label="Até"
                aria-label={`${filter.label}: até`}
                value={ate}
                onChange={(e) => mudarAte(e.target.value)}
                placeholder={String(limites.max)}
              />
            </div>
            <div className="mt-3 flex justify-end gap-2">
              {(active || de || ate) && (
                <Button
                  variant="ghost"
                  size="sm"
                  className="min-h-10"
                  onClick={() => {
                    aplicar("", "");
                    fechar();
                  }}
                >
                  Limpar
                </Button>
              )}
              <Button
                variant="dark"
                size="sm"
                className="min-h-10"
                onClick={() => {
                  aplicar(de, ate);
                  fechar();
                }}
              >
                Aplicar
              </Button>
            </div>
          </m.div>,
          document.body,
        )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { createPortal } from "react-dom";
import { m } from "motion/react";
import { Check, ChevronDown, Search } from "lucide-react";
import { cn } from "@/lib/utils";
import { motionPreset } from "@/lib/motion";
import { popoverPos } from "@/lib/popover-pos";
import {
  chipActive,
  chipBase,
  chipIdle,
  dropdownPanelClass,
  SingleSelectItem,
  useDropdownPortal,
} from "@/components/ui/pilula";
import {
  comDependentes,
  filtrarOpcoes,
  mostrarBuscaPara,
  type EscreverParams,
  type FilterConfig,
  type ParamsDaUrl,
} from "@/components/ui/filter-bar-config";

// Campo de busca reusado pelos dropdowns de select/multiselect (foco visível,
// teclado e tokens semânticos claro/escuro).
function OpcoesBusca({
  value,
  onChange,
  label,
}: {
  value: string;
  onChange: (v: string) => void;
  label: string;
}) {
  return (
    <div className="relative mb-1">
      <Search
        size={14}
        className="absolute top-1/2 left-2 -translate-y-1/2 text-[var(--premium-gray)]"
      />
      <input
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={(e) => e.stopPropagation()}
        placeholder="Buscar..."
        aria-label={`Buscar em ${label}`}
        autoFocus
        className="w-full rounded-[var(--r-sm)] border border-[var(--premium-mist)] bg-[var(--premium-paper)] py-[6px] pr-2 pl-7 text-[13px] text-[var(--premium-ink)] focus:border-[var(--premium-ink)] focus:shadow-[0_0_0_2px_var(--yellow-50)] focus:outline-none"
      />
    </div>
  );
}

export function SingleSelectControl({
  filter,
  searchParams,
  setParams,
}: {
  filter: FilterConfig;
  searchParams: ParamsDaUrl;
  setParams: EscreverParams;
}) {
  const [busca, setBusca] = useState("");
  const { open, setOpen, rect, triggerRef, panelRef, abrir } = useDropdownPortal();
  const Icon = filter.icon;
  const value = searchParams.get(filter.key) ?? "";
  const selectedLabel = filter.options?.find((o) => o.value === value)?.label;
  const mostrarBusca = mostrarBuscaPara(filter);
  const visiveis = filtrarOpcoes(filter, busca);

  function escolher(v: string | null) {
    setParams(comDependentes(filter, v));
    setBusca("");
    setOpen(false);
  }

  return (
    <div className="relative shrink-0">
      <button
        ref={triggerRef}
        onClick={() => {
          setBusca("");
          abrir();
        }}
        aria-label={filter.label}
        aria-haspopup="listbox"
        aria-expanded={open}
        className={cn(chipBase, value ? chipActive : chipIdle)}
      >
        {Icon && <Icon size={14} className="text-[var(--premium-gray)]" />}
        <span>{value && selectedLabel ? `${filter.label}: ${selectedLabel}` : filter.label}</span>
        <ChevronDown size={14} className="-mr-1 text-[var(--premium-gray)]" />
      </button>
      {open &&
        rect &&
        typeof document !== "undefined" &&
        createPortal(
          <m.div
            ref={panelRef}
            {...motionPreset("menu")}
            role="listbox"
            aria-label={filter.label}
            style={popoverPos(rect, Math.max(rect.width, 220), 320)}
            className={dropdownPanelClass}
          >
            {mostrarBusca && <OpcoesBusca value={busca} onChange={setBusca} label={filter.label} />}
            {!busca && (
              <SingleSelectItem
                checked={!value}
                label={filter.placeholder ?? "Todos"}
                onClick={() => escolher(null)}
              />
            )}
            {visiveis.map((o) => (
              <SingleSelectItem
                key={o.value}
                checked={o.value === value}
                label={o.label}
                onClick={() => escolher(o.value)}
              />
            ))}
            {visiveis.length === 0 && (
              <div className="py-4 text-center text-[13px] text-[var(--premium-gray)]">
                Nenhum resultado.
              </div>
            )}
          </m.div>,
          document.body,
        )}
    </div>
  );
}

export function MultiSelectControl({
  filter,
  searchParams,
  setParams,
}: {
  filter: FilterConfig;
  searchParams: ParamsDaUrl;
  setParams: EscreverParams;
}) {
  const [busca, setBusca] = useState("");
  const { open, rect, triggerRef, panelRef, abrir } = useDropdownPortal();
  const Icon = filter.icon;
  const raw = searchParams.get(filter.key);
  const selected = raw ? raw.split(",").filter(Boolean) : [];
  const active = selected.length > 0;
  const mostrarBusca = mostrarBuscaPara(filter);
  const visiveis = filtrarOpcoes(filter, busca);

  function toggle(optValue: string) {
    const next = selected.includes(optValue)
      ? selected.filter((v) => v !== optValue)
      : [...selected, optValue];
    setParams(comDependentes(filter, next.length ? next.join(",") : null));
  }

  return (
    <div className="relative shrink-0">
      <button
        ref={triggerRef}
        onClick={() => {
          setBusca("");
          abrir();
        }}
        aria-haspopup="listbox"
        aria-expanded={open}
        className={cn(chipBase, active ? chipActive : chipIdle)}
      >
        {Icon && <Icon size={14} className="text-[var(--premium-gray)]" />}
        <span>{filter.label}</span>
        {active && (
          <span className="min-w-[16px] rounded-full bg-[var(--premium-ink)] px-[6px] text-center text-[11px] font-bold text-[var(--premium-paper)]">
            {selected.length}
          </span>
        )}
        <ChevronDown size={14} className="-mr-1 text-[var(--premium-gray)]" />
      </button>
      {open &&
        rect &&
        typeof document !== "undefined" &&
        createPortal(
          <m.div
            ref={panelRef}
            {...motionPreset("menu")}
            role="listbox"
            aria-label={filter.label}
            aria-multiselectable
            style={popoverPos(rect, Math.max(rect.width, 220), 320)}
            className={dropdownPanelClass}
          >
            {mostrarBusca && <OpcoesBusca value={busca} onChange={setBusca} label={filter.label} />}
            {visiveis.map((o) => {
              const checked = selected.includes(o.value);
              return (
                <button
                  key={o.value}
                  type="button"
                  onClick={() => toggle(o.value)}
                  role="option"
                  aria-selected={checked}
                  className="flex w-full cursor-pointer items-center gap-2 rounded-[var(--r-sm)] px-2 py-[7px] text-left text-[13px] text-[var(--premium-ink)] hover:bg-[var(--premium-bone)] focus-visible:bg-[var(--premium-bone)] focus-visible:outline-none"
                >
                  <span
                    className={cn(
                      "flex h-4 w-4 shrink-0 items-center justify-center rounded-[4px] border",
                      checked
                        ? "border-[var(--premium-ink)] bg-[var(--premium-ink)] text-[var(--premium-paper)]"
                        : "border-[var(--premium-mist)]",
                    )}
                  >
                    {checked && <Check size={12} />}
                  </span>
                  {o.label}
                </button>
              );
            })}
            {visiveis.length === 0 && (
              <div className="py-4 text-center text-[13px] text-[var(--premium-gray)]">
                Nenhum resultado.
              </div>
            )}
          </m.div>,
          document.body,
        )}
    </div>
  );
}
